<?php
namespace App\Services;use App\Models\Order;use App\Models\Shipment;use Illuminate\Support\Str;use RuntimeException;
class CourierBookingService{public function create(Order $order,string $courier,float $weight):Shipment{abort_unless(in_array($courier,['pathao','steadfast','redx','dhl','fedex']),422);$config=in_array($courier,['dhl','fedex'])?'international':$courier;if(!config("amer_shipping.{$config}.enabled"))throw new RuntimeException(strtoupper($courier).' courier credentials are not configured.');return Shipment::firstOrCreate(['order_id'=>$order->id],['uuid'=>(string)Str::uuid(),'courier'=>$courier,'status'=>'pending_booking','weight'=>$weight]);}public function recordStatus(Shipment $shipment,string $status,?string $external=null):void{$allowed=['pending_booking','booked','picked_up','in_transit','out_for_delivery','delivered','failed','returned','cancelled'];abort_unless(in_array($status,$allowed),422);$shipment->update(['status'=>$status,'delivered_at'=>$status==='delivered'?now():$shipment->delivered_at]);$shipment->events()->create(['status'=>$status,'external_status'=>$external,'occurred_at'=>now()]);}}
